//! Schema definition types for auto-generated database schema.
//!
//! This module defines types that represent the database schema captured via
//! `cori db sync`. The schema definition is auto-generated and should not be
//! manually edited.
//!
//! # Schema Location
//!
//! By convention, the schema is stored at `schema/schema.yaml` relative to the
//! project root.

use serde::{Deserialize, Serialize};
use std::fs;
use std::path::Path;

use super::ConfigError;

/// Auto-generated database schema definition.
///
/// This structure captures the complete database schema including tables,
/// columns, foreign keys, indexes, and enum types. It is generated by
/// `cori db sync` and should not be manually edited.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SchemaDefinition {
    /// Schema version (semver format).
    pub version: String,

    /// Timestamp when the schema was captured.
    pub captured_at: String,

    /// Database information.
    pub database: DatabaseInfo,

    /// List of enabled database extensions.
    #[serde(default)]
    pub extensions: Vec<String>,

    /// Custom enum types defined in the database.
    #[serde(default)]
    pub enums: Vec<EnumDefinition>,

    /// Table definitions.
    pub tables: Vec<TableSchema>,
}

impl SchemaDefinition {
    /// Load schema definition from a YAML file.
    pub fn from_file(path: impl AsRef<Path>) -> Result<Self, ConfigError> {
        let content = fs::read_to_string(path.as_ref())?;
        Self::from_yaml(&content)
    }

    /// Parse schema definition from YAML content.
    pub fn from_yaml(content: &str) -> Result<Self, ConfigError> {
        serde_yaml::from_str(content).map_err(ConfigError::from)
    }

    /// Get a table by name.
    pub fn get_table(&self, name: &str) -> Option<&TableSchema> {
        self.tables.iter().find(|t| t.name == name)
    }

}

/// Database engine and version information.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DatabaseInfo {
    /// Database engine type.
    pub engine: DatabaseEngine,

    /// Database version string.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub version: Option<String>,
}

/// Supported database engines.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
#[derive(Default)]
pub enum DatabaseEngine {
    #[default]
    Postgres,
    Mysql,
    Mariadb,
    Sqlite,
    Sqlserver,
}


/// Custom enum type definition.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EnumDefinition {
    /// Enum type name.
    pub name: String,

    /// Database schema containing the enum.
    #[serde(default = "default_schema")]
    pub schema: String,

    /// Allowed enum values.
    pub values: Vec<String>,
}

/// Table schema definition.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TableSchema {
    /// Table name.
    pub name: String,

    /// Database schema containing the table.
    #[serde(default = "default_schema")]
    pub schema: String,

    /// Column definitions.
    pub columns: Vec<ColumnSchema>,

    /// Primary key column names.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub primary_key: Vec<String>,

    /// Foreign key definitions.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub foreign_keys: Vec<ForeignKey>,

    /// Index definitions.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub indexes: Vec<Index>,
}

impl TableSchema {
    /// Get a column by name.
    pub fn get_column(&self, name: &str) -> Option<&ColumnSchema> {
        self.columns.iter().find(|c| c.name == name)
    }

    /// Get all column names.
    pub fn column_names(&self) -> Vec<&str> {
        self.columns.iter().map(|c| c.name.as_str()).collect()
    }

    /// Check if a column exists.
    pub fn has_column(&self, name: &str) -> bool {
        self.columns.iter().any(|c| c.name == name)
    }

    /// The primary key's columns, in the table's column order.
    pub fn get_primary_key_columns(&self) -> Vec<&ColumnSchema> {
        self.columns.iter().filter(|c| self.primary_key.contains(&c.name)).collect()
    }

    /// The primary key's column names, in key order.
    pub fn get_primary_key_names(&self) -> Vec<&str> {
        self.primary_key.iter().map(|s| s.as_str()).collect()
    }

    /// The table and column a foreign key column references.
    pub fn foreign_key_reference(&self, column: &str) -> Option<(&str, &str)> {
        self.foreign_keys.iter().find_map(|fk| fk.columns.iter().zip(&fk.references.columns).find(|(c, _)| c.as_str() == column).map(|(_, r)| (fk.references.table.as_str(), r.as_str())))
    }
}

/// Column schema definition.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ColumnSchema {
    /// Column name.
    pub name: String,

    /// Generic column type.
    #[serde(rename = "type")]
    pub column_type: ColumnType,

    /// Native database type (e.g., "character varying", "serial").
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub native_type: Option<String>,

    /// Whether the column allows NULL values.
    pub nullable: bool,

    /// Default value or expression.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub default: Option<serde_json::Value>,

    /// Maximum length for string types.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_length: Option<u32>,

    /// Reference to enum type name (if column_type is Enum).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub enum_name: Option<String>,

    /// The column's type as a cast target, schema-qualified and without modifiers (`pg_catalog.int4`, `public.mood`),
    /// from the introspection: the values bound for the column are cast to it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sql_type: Option<String>,
}

impl ColumnSchema {
    /// The database's type name for the column: its native type, else the generic type's name.
    pub fn data_type(&self) -> String {
        self.native_type.clone().unwrap_or_else(|| format!("{:?}", self.column_type).to_lowercase())
    }

    /// The type a value bound for this column is cast to, so that Postgres reads it with the column type's input, as it
    /// reads a quoted literal: the introspected type, else the enum's name, else the SQL name `data_type` gives (a
    /// schema recorded before the types were introspected). None for a text column, which needs no cast, and for a type
    /// `data_type` does not name.
    pub fn cast_type(&self) -> Option<String> {
        const NAMED: &[&str] = &[
            "smallint", "integer", "bigint", "int2", "int4", "int8", "numeric", "decimal", "real", "double precision", "float4", "float8",
            "boolean", "bool", "date", "time without time zone", "time with time zone", "timetz", "timestamp without time zone",
            "timestamp with time zone", "timestamp", "timestamptz", "interval", "uuid", "json", "jsonb", "bytea", "inet", "cidr", "macaddr", "money",
        ];
        let data_type = self.data_type();
        self.sql_type.clone()
            .or_else(|| self.enum_name.as_ref().map(|e| format!("\"{}\"", e.replace('"', "\"\""))))
            .or_else(|| NAMED.contains(&data_type.as_str()).then_some(data_type))
    }

    /// The JSON Schema type of the column's values in a tool's input.
    pub fn json_schema_type(&self) -> &'static str {
        let dt = self.data_type().to_lowercase();
        if dt.contains("int") || dt.contains("serial") {
            "integer"
        } else if dt.contains("numeric") || dt.contains("decimal") || dt.contains("float") || dt.contains("double") || dt.contains("real") {
            "number"
        } else if dt.contains("bool") {
            "boolean"
        } else if dt.contains("json") {
            "object"
        } else if dt.contains("array") {
            "array"
        } else {
            // text, varchar, char, uuid, timestamp, date, etc.
            "string"
        }
    }

    /// The JSON Schema format of the column's values, if any.
    pub fn json_schema_format(&self) -> Option<&'static str> {
        let dt = self.data_type().to_lowercase();
        if dt.contains("uuid") {
            Some("uuid")
        } else if dt.contains("date") && !dt.contains("timestamp") {
            Some("date")
        } else if dt.contains("timestamp") || dt.contains("timestamptz") {
            Some("date-time")
        } else if dt.contains("time") && !dt.contains("timestamp") {
            Some("time")
        } else if dt == "text" && self.name.contains("email") {
            Some("email")
        } else if dt == "text" && self.name.contains("uri") {
            Some("uri")
        } else {
            None
        }
    }
}

/// Generic column types.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
#[derive(Default)]
pub enum ColumnType {
    String,
    Text,
    Integer,
    Bigint,
    Smallint,
    Decimal,
    Float,
    Double,
    Boolean,
    Date,
    Time,
    Datetime,
    Timestamp,
    Uuid,
    Json,
    Jsonb,
    Binary,
    Array,
    Enum,
    #[default]
    Unknown,
}


/// Foreign key definition.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ForeignKey {
    /// Foreign key constraint name.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,

    /// Column names in the current table.
    pub columns: Vec<String>,

    /// Referenced table and columns.
    pub references: ForeignKeyReference,

    /// Action on delete.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub on_delete: Option<ForeignKeyAction>,

    /// Action on update.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub on_update: Option<ForeignKeyAction>,
}

/// Foreign key reference (target table and columns).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ForeignKeyReference {
    /// Referenced table name.
    pub table: String,

    /// Referenced table schema.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub schema: Option<String>,

    /// Referenced column names.
    pub columns: Vec<String>,
}

/// Foreign key actions.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ForeignKeyAction {
    NoAction,
    Restrict,
    Cascade,
    SetNull,
    SetDefault,
}

/// Index definition.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Index {
    /// Index name.
    pub name: String,

    /// Indexed column names.
    pub columns: Vec<String>,

    /// Whether the index enforces uniqueness.
    #[serde(default)]
    pub unique: bool,
}

fn default_schema() -> String {
    "public".to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_schema_definition() {
        let yaml = r#"
version: "1.0.0"
captured_at: "2025-01-08T10:30:00Z"
database:
  engine: postgres
  version: "16.1"
extensions:
  - uuid-ossp
enums:
  - name: ticket_status
    schema: public
    values: [open, in_progress, resolved]
tables:
  - name: customers
    schema: public
    columns:
      - name: id
        type: uuid
        nullable: false
      - name: name
        type: string
        nullable: false
        max_length: 255
    primary_key: [id]
"#;

        let schema = SchemaDefinition::from_yaml(yaml).unwrap();
        assert_eq!(schema.version, "1.0.0");
        assert_eq!(schema.database.engine, DatabaseEngine::Postgres);
        assert_eq!(schema.enums.len(), 1);
        assert_eq!(schema.tables.len(), 1);
        assert_eq!(schema.tables[0].name, "customers");
        assert_eq!(schema.tables[0].columns.len(), 2);
    }

    #[test]
    fn test_get_table() {
        let yaml = r#"
version: "1.0.0"
captured_at: "2025-01-08T10:30:00Z"
database:
  engine: postgres
tables:
  - name: users
    schema: public
    columns:
      - name: id
        type: integer
        nullable: false
  - name: orders
    schema: public
    columns:
      - name: id
        type: integer
        nullable: false
"#;

        let schema = SchemaDefinition::from_yaml(yaml).unwrap();
        assert!(schema.get_table("users").is_some());
        assert!(schema.get_table("orders").is_some());
        assert!(schema.get_table("nonexistent").is_none());
    }

    fn column(name: &str, native: &str) -> ColumnSchema {
        ColumnSchema { name: name.into(), column_type: ColumnType::Unknown, native_type: Some(native.into()), nullable: true, default: None, max_length: None, enum_name: None, sql_type: None }
    }

    #[test]
    fn a_column_type_gives_its_json_schema_type_and_cast() {
        for (native, json) in [("integer", "integer"), ("text", "string"), ("numeric(10,2)", "number"), ("boolean", "boolean"), ("jsonb", "object"), ("uuid", "string")] {
            assert_eq!(column("c", native).json_schema_type(), json, "{native}");
        }
        assert_eq!(column("c", "timestamp with time zone").json_schema_format(), Some("date-time"));
        assert_eq!(column("c", "integer").cast_type().as_deref(), Some("integer"));
        assert_eq!(column("c", "character varying").cast_type(), None, "text needs no cast");
        let mood = ColumnSchema { enum_name: Some("mood".into()), ..column("c", "USER-DEFINED") };
        assert_eq!(mood.cast_type().as_deref(), Some("\"mood\""), "a schema recorded before sql_type still names the enum");
        let typed = ColumnSchema { sql_type: Some("public.mood".into()), ..mood };
        assert_eq!(typed.cast_type().as_deref(), Some("public.mood"));
        let generic = ColumnSchema { native_type: None, column_type: ColumnType::Integer, ..column("c", "") };
        assert_eq!((generic.data_type().as_str(), generic.json_schema_type()), ("integer", "integer"));
    }

    #[test]
    fn keys_are_read_from_the_table() {
        let yaml = "version: \"1\"\ncaptured_at: \"x\"\ndatabase: { engine: postgres }\ntables:\n  - name: orders\n    columns:\n      - { name: id, type: integer, native_type: integer, nullable: false }\n      - { name: customer_id, type: uuid, native_type: uuid, nullable: true }\n    primary_key: [id]\n    foreign_keys:\n      - { name: orders_customer_fk, columns: [customer_id], references: { table: customers, columns: [id] } }\n";
        let schema = SchemaDefinition::from_yaml(yaml).unwrap();
        let orders = schema.get_table("orders").unwrap();
        assert_eq!(orders.get_primary_key_names(), ["id"]);
        assert_eq!(orders.get_primary_key_columns().iter().map(|c| c.name.as_str()).collect::<Vec<_>>(), ["id"]);
        assert_eq!(orders.foreign_key_reference("customer_id"), Some(("customers", "id")));
        assert_eq!(orders.foreign_key_reference("id"), None);
    }
}
